/*
 * Converte os bancos acima em perguntas no mesmo formato de `questions`
 * e as acrescenta ao banco global. O campo `nivel` identifica a série.
 */
(function addSeriesQuestions() {
  if (typeof questions === "undefined" || !Array.isArray(questions)) {
    console.error("FE QUIZ: questions.js precisa ser carregado antes de questions-series.js.");
    return;
  }

  let nextId = questions.reduce((m, q) => Math.max(m, q.id || 0), 0) + 1;

  Object.keys(SERIES_BANKS).forEach((nivel) => {
    SERIES_BANKS[nivel].forEach((r, i) => {
      const [categoria, pergunta, correta, erradas, explicacao] = r;
      const pos = (i * 3 + nivel.length) % 4;
      const alternativas = erradas.slice();
      alternativas.splice(pos, 0, correta);
      questions.push({
        id: nextId++,
        categoria,
        pergunta,
        alternativas,
        resposta: pos,
        explicacao,
        nivel
      });
    });
  });
})();
